WITH Recursive CountiesAboveAvgRep AS (
    SELECT U.Id, U.Reputation, U.CreationDate, U.DisplayName,
        ROW_NUMBER() OVER (ORDER BY U.Reputation DESC) AS RepRank,
        (SELECT COUNT(*) FROM Users WHERE Reputation > U.Reputation) + 1 AS DenseRank
    FROM Users U
    WHERE U.Reputation >= (
        SELECT AVG(Reputation) FROM Users
    )

    UNION ALL

    SELECT U2.Id, U2.Reputation, U2.CreationDate dreams dreams replace advanced possessions precinct represents .
